// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;
    function setUp() public { c = new DAO(); }
    function testRegression_property() public {
        c.init(address(0x1), address(0x2), address(0x3));

        c.newGrantProposal(address(0x4), 100);

        c.newGrantProposal(address(0x5), 200);

        c.voteProposal(1);

        c.voteProposal(2);

        c.cancelProposal(1, 2);

        uint votesAfterFirstCancel = c.mapPID_votes(1);

        c.newGrantProposal(address(0x6), 300);
        c.voteProposal(3);
        c.cancelProposal(1, 3);

        uint votesAfterSecondCancel = c.mapPID_votes(1);

        assertTrue(votesAfterSecondCancel == 0, "mapPID_votes[old] should be 0 after two cancels");
    }
}
